import{_ as i,o as a,c as t,a2 as r}from"./chunks/framework.BXzK3EA4.js";const g=JSON.parse('{"title":"VPS Monitoring Features Guide","description":"","frontmatter":{"title":"VPS Monitoring Features Guide"},"headers":[],"relativePath":"operations-knowledge-base/vps/vps-monitoring-features-guide.md","filePath":"operations-knowledge-base/vps/vps-monitoring-features-guide.md","lastUpdated":1794292919000}'),s={name:"operations-knowledge-base/vps/vps-monitoring-features-guide.md"};function o(n,e,l,h,u,c){return a(),t("div",null,[...e[0]||(e[0]=[r('<h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>This document introduces the monitoring and usage statistics features available in the VPS control panel. It helps customers monitor server performance, resource utilization, and network traffic for daily operations and performance analysis.</p><p><strong>Supported Product:</strong></p><ul><li>VPS</li></ul><hr><h2 id="_1-accessing-the-monitoring-page" tabindex="-1">1. Accessing the Monitoring Page <a class="header-anchor" href="#_1-accessing-the-monitoring-page" aria-label="Permalink to &quot;1. Accessing the Monitoring Page&quot;">​</a></h2><h3 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h3><ol><li>Log in to the <strong>Raksmart Client Portal</strong>.</li><li>Go to <strong>Product Management → VPS</strong>.</li><li>Select the VPS you want to manage.</li><li>Enter the VPS management page.</li><li>By default, you will be taken to the <strong>Charts</strong> (Monitoring) page.</li></ol><p>The following tabs are available:</p><ul><li>Charts</li><li>Usage</li></ul><hr><h2 id="_2-charts-real-time-monitoring" tabindex="-1">2. Charts (Real-Time Monitoring) <a class="header-anchor" href="#_2-charts-real-time-monitoring" aria-label="Permalink to &quot;2. Charts (Real-Time Monitoring)&quot;">​</a></h2><p>The <strong>Charts</strong> page provides real-time monitoring of your VPS resources, allowing you to view the current operating status of your server.</p><p>The following monitoring metrics are available:</p><ul><li>CPU Usage</li><li>Disk I/O</li><li>Memory Usage</li><li>Network Traffic</li></ul><p>These charts help you determine whether:</p><ul><li>CPU utilization remains consistently high.</li><li>There is abnormal disk read/write activity.</li><li>Memory resources are insufficient.</li><li>Network traffic is unusually high.</li></ul><p><strong>Note:</strong></p><p>Monitoring data is updated continuously and can be used for daily performance monitoring and troubleshooting.</p><hr><h2 id="cpu-usage" tabindex="-1">CPU Usage <a class="header-anchor" href="#cpu-usage" aria-label="Permalink to &quot;CPU Usage&quot;">​</a></h2><p>Displays the current CPU utilization of the VPS.</p><p>Typical use cases include:</p><ul><li>Monitoring long-term CPU usage.</li><li>Identifying processes consuming excessive CPU resources.</li><li>Analyzing CPU usage during peak business hours.</li></ul><hr><h2 id="disk-i-o" tabindex="-1">Disk I/O <a class="header-anchor" href="#disk-i-o" aria-label="Permalink to &quot;Disk I/O&quot;">​</a></h2><p>Displays disk read and write activity.</p><p>You can select different disks (such as the system disk or data disk) for monitoring.</p><p>Typical use cases include:</p><ul><li>Monitoring disk I/O performance.</li><li>Identifying unusually high disk activity.</li><li>Troubleshooting performance issues caused by disk operations.</li></ul><hr><h2 id="memory-usage" tabindex="-1">Memory Usage <a class="header-anchor" href="#memory-usage" aria-label="Permalink to &quot;Memory Usage&quot;">​</a></h2><p>Displays the current memory usage of the VPS.</p><p>Typical use cases include:</p><ul><li>Monitoring memory consumption.</li><li>Determining whether memory resources are sufficient.</li><li>Analyzing memory usage trends over time.</li></ul><hr><h2 id="network-traffic" tabindex="-1">Network Traffic <a class="header-anchor" href="#network-traffic" aria-label="Permalink to &quot;Network Traffic&quot;">​</a></h2><p>Displays the real-time network traffic of the VPS.</p><p>You can monitor the incoming and outgoing traffic of the network interface.</p><p>Typical use cases include:</p><ul><li>Monitoring current network usage.</li><li>Analyzing business traffic.</li><li>Identifying abnormal network activity.</li></ul><hr><h2 id="_3-usage-statistics" tabindex="-1">3. Usage Statistics <a class="header-anchor" href="#_3-usage-statistics" aria-label="Permalink to &quot;3. Usage Statistics&quot;">​</a></h2><p>The <strong>Usage</strong> page displays historical network traffic statistics for your VPS.</p><p>The page supports:</p><ul><li>Viewing historical traffic usage.</li><li>Selecting a specific time range.</li><li>Customizing the start and end dates for traffic statistics.</li></ul><p>Customers can review network traffic usage over a selected period to better understand bandwidth consumption and traffic trends.</p><p><strong>Note:</strong></p><p>The Usage page is intended for network traffic statistics. Depending on the selected time range, there may be a slight delay before the latest data is displayed.</p><hr><h2 id="_4-frequently-asked-questions" tabindex="-1">4. Frequently Asked Questions <a class="header-anchor" href="#_4-frequently-asked-questions" aria-label="Permalink to &quot;4. Frequently Asked Questions&quot;">​</a></h2><h3 id="q1-why-is-there-no-data-displayed-in-the-monitoring-charts" tabindex="-1">Q1: Why is there no data displayed in the monitoring charts? <a class="header-anchor" href="#q1-why-is-there-no-data-displayed-in-the-monitoring-charts" aria-label="Permalink to &quot;Q1: Why is there no data displayed in the monitoring charts?&quot;">​</a></h3><p>Please check the following:</p><ul><li>Whether the VPS is running normally.</li><li>Whether sufficient time has been allowed for monitoring data to be collected.</li><li>Whether the correct monitoring item has been selected.</li></ul><p>If the VPS has just been created or restarted, monitoring data may take some time to appear.</p><hr><h3 id="q2-what-should-i-do-if-cpu-usage-remains-high" tabindex="-1">Q2: What should I do if CPU usage remains high? <a class="header-anchor" href="#q2-what-should-i-do-if-cpu-usage-remains-high" aria-label="Permalink to &quot;Q2: What should I do if CPU usage remains high?&quot;">​</a></h3><p>Log in to your VPS and check:</p><ul><li>Whether any applications are consuming excessive CPU resources.</li><li>Whether there are abnormal processes running.</li><li>Whether scheduled tasks are continuously using CPU resources.</li></ul><p>If the high CPU usage is caused by normal business workloads, consider upgrading your VPS configuration.</p><hr><h3 id="q3-why-is-memory-usage-very-high" tabindex="-1">Q3: Why is memory usage very high? <a class="header-anchor" href="#q3-why-is-memory-usage-very-high" aria-label="Permalink to &quot;Q3: Why is memory usage very high?&quot;">​</a></h3><p>High memory usage does not necessarily indicate a problem.</p><p>Linux systems commonly use available memory as file cache. It is recommended to evaluate memory usage together with available memory and your actual workload.</p><hr><h3 id="q4-why-is-disk-i-o-continuously-high" tabindex="-1">Q4: Why is Disk I/O continuously high? <a class="header-anchor" href="#q4-why-is-disk-i-o-continuously-high" aria-label="Permalink to &quot;Q4: Why is Disk I/O continuously high?&quot;">​</a></h3><p>Possible causes include:</p><ul><li>Frequent database read/write operations.</li><li>Large file transfers.</li><li>Applications performing continuous disk operations.</li></ul><p>It is recommended to log in to the server for further investigation.</p><hr><h3 id="q5-can-i-view-historical-traffic-statistics" tabindex="-1">Q5: Can I view historical traffic statistics? <a class="header-anchor" href="#q5-can-i-view-historical-traffic-statistics" aria-label="Permalink to &quot;Q5: Can I view historical traffic statistics?&quot;">​</a></h3><p>Yes.</p><p>The <strong>Usage</strong> page allows you to select a custom date range and view network traffic statistics for the selected period.</p><hr><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><p>⚠️ Monitoring data is intended to reflect server resource utilization and does not necessarily indicate a system issue.</p><p>⚠️ If the VPS has just been created, restarted, or restored, monitoring data may take some time to become available.</p><p>⚠️ The <strong>Usage</strong> page supports custom date range queries, allowing you to review historical traffic statistics as needed.</p><p>⚠️ If CPU usage, memory usage, disk I/O, or network traffic remains abnormally high for an extended period, it is recommended to first inspect the server and running applications before considering resource optimization or a VPS upgrade.</p>',79)])])}const p=i(s,[["render",o]]);export{g as __pageData,p as default};
